//! display/dc/inc/hw/mcif_wb.h + mmhubbub/dcn20/dcn20_mmhubbub.{h,c}
//! (Linux 6.18.55), with the `mcif_wb20_regs`/`mcif_wb20_shift`/`mcif_wb20_mask`
//! table of dcn20_resource.c: the multi-media hub writeback (MCIF-WB) of
//! Renoir's resource pool. Renoir reuses the dcn20 MCIF-WB; the pool creates
//! `res_cap_rn.num_dwb` (1) of them.
//!
//! `dcn20_mmhubbub_create` → `dcn20_mmhubbub_construct` stores the instance,
//! funcs identity and register pointers; it writes no register (the writeback
//! programming is hwss-stage). The register tables are machine-generated by
//! `dcgen.py` from `MCIF_WB_COMMON_REG_LIST_DCN2_0` /
//! `MCIF_WB_COMMON_MASK_SH_LIST_DCN2_0`.
#![allow(dead_code)]

use crate::dc_resource::resource_pool;
use crate::regs::*;
use alloc::boxed::Box;

/// Which `mcif_wb_funcs` vtable the base points at (dcn20_mmhubbub.c).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum mcif_wb_funcs {
    dcn20_mmhubbub_funcs,
}

/// `struct mcif_wb` (inc/hw/mcif_wb.h): the writeback hub base. The construct
/// touches funcs and inst (Linux' `ctx` is not stored, see `clock_source`).
#[derive(Default)]
pub struct mcif_wb {
    pub funcs: Option<mcif_wb_funcs>,
    pub inst: u32,
}

/// `struct dcn20_mmhubbub` (dcn20_mmhubbub.h): the concrete MCIF-WB.
#[derive(Default)]
pub struct dcn20_mmhubbub {
    pub base: mcif_wb,
    pub mcif_wb_regs: Option<&'static dcn20_mmhubbub_registers>,
    pub mcif_wb_shift: Option<&'static dcn20_mmhubbub_shift>,
    pub mcif_wb_mask: Option<&'static dcn20_mmhubbub_mask>,
}

/// `dcn20_mmhubbub_construct` (dcn20_mmhubbub.c): store the instance, funcs and
/// registers.
pub fn dcn20_mmhubbub_construct(
    mcif_wb20: &mut dcn20_mmhubbub,
    mcif_wb_regs: &'static dcn20_mmhubbub_registers,
    mcif_wb_shift: &'static dcn20_mmhubbub_shift,
    mcif_wb_mask: &'static dcn20_mmhubbub_mask,
    inst: u32,
) {
    mcif_wb20.base.inst = inst;
    mcif_wb20.base.funcs = Some(mcif_wb_funcs::dcn20_mmhubbub_funcs);
    mcif_wb20.mcif_wb_regs = Some(mcif_wb_regs);
    mcif_wb20.mcif_wb_shift = Some(mcif_wb_shift);
    mcif_wb20.mcif_wb_mask = Some(mcif_wb_mask);
}

/// `dcn20_mmhubbub_create` (dcn20_resource.c): allocate and construct `num_dwb`
/// MCIF-WBs into `pool.mcif_wb`. Returns true (allocation does not fail here).
pub fn dcn20_mmhubbub_create(pool: &mut resource_pool) -> bool {
    let pipe_count = pool.res_cap.unwrap().num_dwb;
    for i in 0..pipe_count as usize {
        let mut mcif_wb20 = Box::new(dcn20_mmhubbub::default());
        dcn20_mmhubbub_construct(&mut mcif_wb20, &MCIF_REGS[i], &MCIF_SHIFT, &MCIF_MASK, i as u32);
        pool.mcif_wb[i] = Some(mcif_wb20);
    }
    true
}

